// Parsed Claude-Antwort + tagged mit fb. Verzweigt später im Code-Block.
const fb = $('PDF → Base64 + Kontext').first().json.erkannter_fb;
const einreichung_id = $('PDF → Base64 + Kontext').first().json.einreichung_id;
const raw = $input.first().json;
const content = raw.content?.[0]?.text;
if (!content) throw new Error('Claude lieferte keinen Text: ' + JSON.stringify(raw).slice(0, 400));
let extr;
try {
  const cleaned = content.trim().replace(/^```json\n?/, '').replace(/\n?```$/, '');
  extr = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Claude-Antwort kein JSON: ' + content.slice(0, 400));
}
// Sanity-Check: NOT-NULL-Felder von apl.antraege
const pflicht = ['einrichtung','ansprechpartner','strasse','plz','ort','telefon','email','bankname','iban','bic'];
const fehlend = pflicht.filter(k => !extr[k] || (typeof extr[k] === 'string' && extr[k].trim() === ''));
if (fehlend.length > 0) {
  throw new Error('OCR-Pflichtfelder fehlen: ' + fehlend.join(', '));
}
// Detail-Pflichten
const detailPflicht = {
  'I': ['projekt_titel'],
  'II': ['ehrenamt_titel'],
  'III': ['variante'],
  'IV': ['vorhaben_titel','kurzbeschreibung','geplante_massnahmen'],
};
const dpf = (detailPflicht[fb] || []).filter(k => !extr[k] || (typeof extr[k] === 'string' && extr[k].trim() === ''));
if (dpf.length > 0) {
  // FB-I-Fallback: wenn projekt_titel fehlt → einrichtung übernehmen
  if (fb === 'I' && dpf.includes('projekt_titel')) {
    extr.projekt_titel = extr.einrichtung;
  } else if (fb === 'II' && dpf.includes('ehrenamt_titel')) {
    extr.ehrenamt_titel = extr.einrichtung;
  } else {
    throw new Error('FB-' + fb + '-Detail-Pflichtfelder fehlen: ' + dpf.join(', '));
  }
}
// haushaltsjahr-Default = aktuelles Jahr
if (!extr.haushaltsjahr) extr.haushaltsjahr = new Date().getFullYear();
return [{ json: { extrahiert: extr, einreichung_id, fb } }];

// Baut den FB-spezifischen Detail-Payload + setzt antrag_id durch.
const inserted = $input.first().json;
const antrag = Array.isArray(inserted) ? inserted[0] : inserted;
if (!antrag || !antrag.id) {
  throw new Error('INSERT apl.antraege lieferte keine id: ' + JSON.stringify(inserted).slice(0, 400));
}
const pv = $('Parse + Validate OCR').first().json;
const e = pv.extrahiert;
let table, payload;
switch (pv.fb) {
  case 'I':
    table = 'fb_i_projekt';
    payload = {
      antrag_id: antrag.id,
      projekt_titel: e.projekt_titel,
      laufzeit: e.laufzeit ?? null,
      stadtteil: e.stadtteil ?? null,
      personalkosten_euro: e.personalkosten_euro ?? null,
      sachkosten_euro: e.sachkosten_euro ?? null,
    };
    break;
  case 'II':
    table = 'fb_ii_ehrenamt';
    payload = {
      antrag_id: antrag.id,
      ehrenamt_titel: e.ehrenamt_titel,
      anzahl_helfer_vorjahr: e.anzahl_helfer_vorjahr ?? null,
      gesamt_helferstunden_vorjahr: e.gesamt_helferstunden_vorjahr ?? null,
      direkter_kontakt_senioren: e.direkter_kontakt_senioren ?? false,
    };
    break;
  case 'III':
    table = 'fb_iii_variante';
    payload = {
      antrag_id: antrag.id,
      variante: e.variante,
      a_anmerkung: e.a_anmerkung ?? null,
      b_anzahl_veranstaltungen: e.b_anzahl_veranstaltungen ?? null,
      b_teilnehmer_senioren: e.b_teilnehmer_senioren ?? null,
      b_teilnehmer_generationen: e.b_teilnehmer_generationen ?? null,
      b_stadtbewohner_anteil: e.b_stadtbewohner_anteil ?? null,
      b_quartierstreffen_teilnahme: e.b_quartierstreffen_teilnahme ?? null,
      b_quartiere: e.b_quartiere ?? null,
      b_quartier_person_name: e.b_quartier_person_name ?? null,
      c_treffen_schwelle: e.c_treffen_schwelle ?? null,
      c_teilnehmer_durchschnitt: e.c_teilnehmer_durchschnitt ?? null,
      c_quartierstreffen_anzahl: e.c_quartierstreffen_anzahl ?? null,
      c_quartier_kooperation: e.c_quartier_kooperation ?? null,
      c_quartier_person_name: e.c_quartier_person_name ?? null,
      d_hauptamt_name: e.d_hauptamt_name ?? null,
      d_hauptamt_stunden_woche: e.d_hauptamt_stunden_woche ?? null,
      d_hauptamt_stunden_monat: e.d_hauptamt_stunden_monat ?? null,
    };
    break;
  case 'IV':
    table = 'fb_iv_freitext';
    payload = {
      antrag_id: antrag.id,
      vorhaben_titel: e.vorhaben_titel,
      kurzbeschreibung: (e.kurzbeschreibung || '').slice(0, 1000),
      geplante_massnahmen: e.geplante_massnahmen,
      beantragte_summe_euro: e.beantragte_summe_euro ?? null,
      laufzeit: e.laufzeit ?? null,
    };
    break;
  default:
    throw new Error('Unbekannter FB: ' + pv.fb);
}
return [{ json: {
  antrag_id: antrag.id,
  antragsnummer: antrag.antragsnummer,
  detail_table: table,
  detail_payload: payload,
  einreichung_id: pv.einreichung_id,
  extrahiert: e,
  fb: pv.fb,
}}];

// Sammelt Fehler-Kontext aus dem Error-Trigger.
const body = $('Webhook (Supabase NOTIFY)').first()?.json?.body || {};
const err = $input.first().json;
const msg = err?.error?.message || err?.message || JSON.stringify(err).slice(0, 600);
return [{ json: {
  einreichung_id: body.einreichung_id || null,
  fehler_text: 'OCR-Pipeline: ' + msg,
}}];
